const items = $input.all();
const deal = items[0].json;

const customer = deal.customer || deal.company || 'New Customer';
const amount = parseFloat(deal.amount || deal.value || 0);
const rep = deal.salesRep || deal.rep || '';
const product = deal.product || deal.plan || 'Enterprise';
const dealType = deal.type || 'New Business';

const celebrations = [
  ':tada: :champagne: :confetti_ball:',
  ':rocket: :star2: :trophy:',
  ':moneybag: :fire: :dart:',
  ':medal: :sparkles: :chart_with_upwards_trend:'
];
const celebration = celebrations[Math.floor(Math.random() * celebrations.length)];

let tierEmoji = ':star:';
if (amount >= 100000) tierEmoji = ':gem:';
else if (amount >= 50000) tierEmoji = ':trophy:';
else if (amount >= 10000) tierEmoji = ':medal:';

const slackMsg = `${celebration}\n\n` +
  `${tierEmoji} *DEAL CLOSED!* ${tierEmoji}\n\n` +
  `*Customer:* ${customer}\n` +
  `*Amount:* $${amount.toLocaleString()}\n` +
  `*Product:* ${product}\n` +
  `*Type:* ${dealType}\n` +
  `*Closed by:* <@${rep}>\n\n` +
  `Congrats to the team! :clap:`;

return [{json: {
  customer,
  amount,
  rep,
  product,
  dealType,
  slackMsg,
  closedAt: new Date().toISOString(),
  quarter: `Q${Math.ceil((new Date().getMonth() + 1) / 3)} ${new Date().getFullYear()}`
}}];

